 const speedK=Math.round(state.vz*3.6),scoreText=Math.floor(state.score).toString().padStart(6,'0');document.querySelector('#speed').textContent=speedK;document.querySelector('#score').textContent=scoreText;document.querySelector('#distance').textContent=Math.floor(state.distance).toString();document.querySelector('#meter').style.width=clamp(state.airTime/1.35*100,0,100)+'%';document.querySelector('#multiplier').textContent='×'+(1+state.combo*.2+state.bar*.15).toFixed(1);
